Apocalipse 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o Senhor tem contra a igreja em Éfeso?","o":["Deixou o seu primeiro amor","Tolera a mulher Jezabel","Mantém a doutrina de Balaão","Negou a fé"],"c":0,"v":4,"e":"No versículo 4, o Senhor diz à igreja em Éfeso que tem contra ela o fato de ter deixado o seu primeiro amor."},
 {"t":"multipla","p":"O que é prometido ao vencedor na carta à igreja em Éfeso?","o":["O maná escondido","Alimentar-se da árvore da vida","A estrela da manhã","Autoridade sobre as nações"],"c":1,"v":7,"e":"O versículo 7 promete ao vencedor que se alimente da árvore da vida, que está no paraíso de Deus."},
 {"t":"multipla","p":"Segundo a carta a Esmirna, quem está prestes a lançar alguns na prisão?","o":["Os nicolaítas","Jezabel","O diabo","Os falsos apóstolos"],"c":2,"v":10,"e":"O versículo 10 diz que o diabo está prestes a lançar alguns deles na prisão, para que sejam provados."},
 {"t":"multipla","p":"Quem é chamado de fiel testemunha, morto em Pérgamo?","o":["Balac","Antipas","Estêvão","Timóteo"],"c":1,"v":13,"e":"O versículo 13 menciona Antipas, fiel testemunha, que foi morto em Pérgamo, onde Satanás habita."},
 {"t":"multipla","p":"Quem a igreja em Tiatira tolera que ensine e seduza os servos do Senhor?","o":["Balaão","Os nicolaítas","Os que se dizem judeus","Jezabel, que se diz profetisa"],"c":3,"v":20,"e":"O versículo 20 diz que a igreja em Tiatira tolera Jezabel, que se autodenomina profetisa."},
 {"t":"cv","p":"Na carta a Tiatira, o Senhor diz que as últimas obras da igreja são mais numerosas do que as primeiras.","c":true,"v":19,"e":"O versículo 19 afirma que as últimas obras da igreja em Tiatira são mais numerosas do que as primeiras."},
 {"t":"cv","p":"Jezabel recebeu tempo para se arrepender e se arrependeu de sua prostituição.","c":false,"v":21,"e":"O versículo 21 diz que lhe foi dado tempo para se arrepender, mas ela não quis se arrepender."},
 {"t":"cv","p":"Ao vencedor em Tiatira, o Senhor promete dar a estrela da manhã.","c":true,"v":28,"e":"O versículo 28 diz: \"E eu também lhe darei a estrela da manhã\"."}
]}

Apocalipse 8 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que aconteceu quando o sétimo selo foi aberto?","o":["Houve um grande terremoto","Houve silêncio no céu por cerca de meia hora","Caiu fogo do céu sobre a terra","Os anjos cantaram diante do trono"],"c":1,"v":1,"e":"O versículo 1 diz que, aberto o sétimo selo, houve silêncio no céu por aproximadamente meia hora."},
 {"t":"multipla","p":"O que subiu à presença de Deus junto com o fumo do incenso?","o":["As orações dos santos","O sangue dos mártires","O cântico dos anciãos","O som das sete trombetas"],"c":0,"v":4,"e":"O versículo 4 diz que o fumo do incenso subiu à presença de Deus juntamente com as orações dos santos."},
 {"t":"multipla","p":"O que o anjo fez com o incensário depois de enchê-lo com o fogo do altar?","o":["Colocou-o de volta sobre o altar","Entregou-o ao primeiro anjo","Lançou-o sobre a terra","Derramou-o sobre o mar"],"c":2,"v":5,"e":"O versículo 5 diz que o anjo encheu o incensário com o fogo do altar e o lançou sobre a terra."},
 {"t":"multipla","p":"O que foi lançado sobre a terra quando o primeiro anjo tocou a trombeta?","o":["Uma grande estrela ardendo como tocha","Uma grande montanha ardendo em chamas","Saraiva e fogo misturado com sangue","Gafanhotos e fumaça"],"c":2,"v":7,"e":"O versículo 7 diz que, no toque da primeira trombeta, houve saraiva e fogo misturado com sangue lançados sobre a terra."},
 {"t":"multipla","p":"O que aconteceu com o mar quando o segundo anjo tocou a trombeta?","o":["Um terço do mar se tornou em sangue","O mar inteiro secou","Um terço do mar ficou amargo","O mar se transformou em gelo"],"c":0,"v":8,"e":"O versículo 8 diz que algo como uma grande montanha ardendo foi atirado ao mar, e um terço do mar se tornou em sangue."},
 {"t":"cv","p":"A estrela que caiu no toque da terceira trombeta se chamava Absinto, e muitos homens morreram por causa das águas que se tornaram amargas.","c":true,"v":11,"e":"O versículo 11 diz que o nome da estrela era Absinto e que muitos homens morreram por causa das águas amargas."},
 {"t":"cv","p":"No toque da quarta trombeta, o sol, a lua e as estrelas se apagaram por completo.","c":false,"v":12,"e":"O versículo 12 diz que foi ferida apenas a terça parte do sol, da lua e das estrelas."},
 {"t":"cv","p":"Uma águia voando pelo meio do céu anunciou \"Ai! Ai! Ai!\" aos que habitam na terra, por causa das trombetas que ainda iam tocar.","c":true,"v":13,"e":"O versículo 13 diz que uma águia voava pelo meio do céu anunciando os ais por causa das trombetas dos três anjos que ainda iam tocar."}
]}

Apocalipse 12 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como estava vestida a mulher que apareceu como grande sinal no céu?","o":["De sol","De linho branco","De púrpura e escarlata","De saco"],"c":0,"v":1,"e":"No versículo 1, a mulher aparece vestida de sol, com a lua sob os pés e uma coroa de doze estrelas."},
 {"t":"multipla","p":"Por que o dragão se deteve diante da mulher que estava para dar à luz?","o":["Para adorá-la","Para levá-la ao deserto","Para devorar o filho dela assim que nascesse","Para tirar-lhe a coroa de estrelas"],"c":2,"v":4,"e":"O versículo 4 diz que o dragão se deteve diante da mulher a fim de devorar o filho dela assim que nascesse."},
 {"t":"multipla","p":"O que aconteceu com o filho varão depois que nasceu?","o":["Foi levado com a mãe ao deserto","Foi arrebatado para Deus e para o seu trono","Foi escondido na terra","Foi entregue aos anjos de Miguel"],"c":1,"v":5,"e":"No versículo 5, o filho é arrebatado para Deus e para o seu trono."},
 {"t":"multipla","p":"Quem pelejou contra o dragão na batalha no céu?","o":["Gabriel e seus anjos","Os vinte e quatro anciãos","O Cordeiro sozinho","Miguel e seus anjos"],"c":3,"v":7,"e":"O versículo 7 diz que Miguel e seus anjos pelejaram contra o dragão."},
 {"t":"multipla","p":"Como os irmãos venceram o acusador?","o":["Pela espada e pelo escudo","Pelo sangue do Cordeiro e pela palavra do testemunho","Pelo jejum e pela oração","Pela ajuda da grande águia"],"c":1,"v":11,"e":"O versículo 11 diz que eles o venceram pelo sangue do Cordeiro e pela palavra do testemunho que deram."},
 {"t":"cv","p":"O grande dragão expulso do céu é chamado de antiga serpente, Diabo e Satanás.","c":true,"v":9,"e":"O versículo 9 identifica o grande dragão como a antiga serpente, chamada Diabo e Satanás."},
 {"t":"cv","p":"O diabo desceu à terra tranquilo, sabendo que ainda tinha muito tempo.","c":false,"v":12,"e":"O versículo 12 diz que o diabo desceu cheio de grande cólera, sabendo que lhe resta pouco tempo."},
 {"t":"cv","p":"Quando a serpente lançou águas como um rio atrás da mulher, a terra abriu a boca e engoliu o rio.","c":true,"v":16,"e":"O versículo 16 diz que a terra socorreu a mulher, abriu a boca e engoliu o rio que o dragão lançou."}
]}

Apocalipse 11 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que foi dado a João para medir o santuário de Deus?","o":["Uma cana semelhante a uma vara","Uma corda de linho","Uma régua de ouro","Um prumo de bronze"],"c":0,"v":1,"e":"No versículo 1, João diz: \"Foi-me dada uma cana semelhante a uma vara\"."},
 {"t":"multipla","p":"Como as duas testemunhas são descritas?","o":["Os dois querubins e as duas trombetas","As duas estrelas e as duas lâmpadas","As duas oliveiras e os dois candelabros","Os dois tronos e as duas coroas"],"c":2,"v":4,"e":"O versículo 4 diz que elas são \"as duas oliveiras e os dois candelabros\" diante do Senhor da terra."},
 {"t":"multipla","p":"Quem faz guerra contra as duas testemunhas e as mata?","o":["Os reis da terra","A besta que surge do abismo","Um anjo vindo do céu","Os povos da grande cidade"],"c":1,"v":7,"e":"O versículo 7 diz que, concluído o testemunho, \"a besta que surge do abismo\" as vencerá e matará."},
 {"t":"multipla","p":"Como é chamada, espiritualmente, a grande cidade onde os corpos ficam expostos?","o":["Babilônia e Nínive","Gomorra e Assíria","Tiro e Sidom","Sodoma e Egito"],"c":3,"v":8,"e":"O versículo 8 diz que a grande cidade é chamada, espiritualmente, \"Sodoma e Egito\"."},
 {"t":"multipla","p":"O que fizeram os sobreviventes do grande terremoto?","o":["Fugiram para os montes","Blasfemaram contra Deus","Deram glória ao Deus do céu","Sepultaram as duas testemunhas"],"c":2,"v":13,"e":"O versículo 13 diz que os sobreviventes, aterrorizados, \"deram glória ao Deus do céu\"."},
 {"t":"cv","p":"Os habitantes da terra lamentaram a morte das duas testemunhas.","c":false,"v":10,"e":"O versículo 10 diz que eles se alegraram e enviaram presentes uns aos outros, porque os dois profetas os atormentavam."},
 {"t":"cv","p":"Depois que o sétimo anjo tocou a trombeta, os vinte e quatro anciãos continuaram sentados em seus tronos.","c":false,"v":16,"e":"O versículo 16 diz que os anciãos se prostraram sobre o rosto e adoraram a Deus."},
 {"t":"cv","p":"Quando o santuário de Deus se abriu no céu, a arca da aliança foi vista nele.","c":true,"v":19,"e":"O versículo 19 diz que \"a arca da aliança foi vista em Seu santuário\"."}
]}

Apocalipse 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que os quatro anjos nos cantos da terra estavam segurando?","o":["Os quatro ventos da terra","Quatro trombetas","Os sete selos","As chaves do abismo"],"c":0,"v":1,"e":"No versículo 1, os quatro anjos estão conservando seguros os quatro ventos da terra para que nenhum vento soprasse."},
 {"t":"multipla","p":"De onde vinha o outro anjo que trazia o selo do Deus vivo?","o":["Do mar","Da direção do sol nascente","De dentro do trono","Da direção do pôr do sol"],"c":1,"v":2,"e":"No versículo 2, João vê outro anjo subindo da direção do sol nascente, trazendo o selo do Deus vivo."},
 {"t":"multipla","p":"Qual era o número dos selados das tribos de Israel?","o":["Doze mil","Vinte e quatro mil","Cento e quarenta e quatro mil","Sete mil"],"c":2,"v":4,"e":"No versículo 4, João ouve que os selados eram cento e quarenta e quatro mil, de todas as tribos de Israel."},
 {"t":"multipla","p":"O que a grande multidão segurava nas mãos?","o":["Harpas","Coroas","Lâmpadas","Palmas"],"c":3,"v":9,"e":"No versículo 9, a multidão está em pé diante do trono, com vestes brancas e palmas nas mãos."},
 {"t":"multipla","p":"Segundo o ancião, de onde vieram os que estavam vestidos de branco?","o":["Da grande tribulação","Do deserto","Das doze tribos de Israel","Da cidade santa"],"c":0,"v":14,"e":"No versículo 14, o ancião diz que esses são os que vieram da grande tribulação."},
 {"t":"cv","p":"O anjo mandou danificar a terra e o mar antes de selarem os servos de Deus.","c":false,"v":3,"e":"No versículo 3, o anjo manda não danificar a terra, o mar e as árvores até que os servos de Deus sejam selados na fronte."},
 {"t":"cv","p":"Quem perguntou quem eram os vestidos de branco foi um dos quatro seres viventes.","c":false,"v":13,"e":"No versículo 13, quem faz a pergunta é um dos anciãos."},
 {"t":"cv","p":"O Cordeiro guiará a multidão para as fontes da água da vida, e Deus lhes enxugará dos olhos toda lágrima.","c":true,"v":17,"e":"O versículo 17 diz que o Cordeiro os guiará às fontes da água da vida e que Deus enxugará toda lágrima dos seus olhos."}
]}

Apocalipse 16 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Sobre quem vieram as úlceras quando o primeiro anjo derramou a sua taça?","o":["Sobre os que tinham o sinal da besta e adoravam a sua imagem","Sobre os santos e os profetas","Sobre os reis que vêm do Oriente","Sobre os que moravam nas ilhas"],"c":0,"v":2,"e":"O versículo 2 diz que as úlceras vieram sobre os homens que tinham o sinal da besta e adoravam a sua imagem."},
 {"t":"multipla","p":"O que aconteceu com o mar quando o segundo anjo derramou a sua taça?","o":["Secou por completo","Ficou coberto de trevas","Tornou-se em sangue como de morto","Pegou fogo"],"c":2,"v":3,"e":"O versículo 3 diz que o mar se tornou em sangue como de morto e morreu todo ser vivente nele."},
 {"t":"multipla","p":"Segundo o anjo das águas, por que os homens receberam sangue para beber?","o":["Porque adoraram ídolos de ouro","Porque derramaram o sangue dos santos e dos profetas","Porque secaram o rio Eufrates","Porque fugiram para os montes"],"c":1,"v":6,"e":"O versículo 6 explica que eles derramaram o sangue dos santos e dos profetas, e por isso receberam sangue para beber."},
 {"t":"multipla","p":"O que aconteceu quando o sexto anjo derramou a sua taça sobre o rio Eufrates?","o":["O rio se tornou em sangue","O rio transbordou sobre as cidades","Saíram rãs do rio","As águas secaram para preparar o caminho dos reis do Oriente"],"c":3,"v":12,"e":"O versículo 12 diz que as águas do Eufrates secaram para que se preparasse o caminho dos reis que vêm do Oriente."},
 {"t":"multipla","p":"Com o que se pareciam os três espíritos imundos que saíram da boca do dragão, da besta e do falso profeta?","o":["Com gafanhotos","Com rãs","Com serpentes","Com escorpiões"],"c":1,"v":13,"e":"O versículo 13 diz que os três espíritos imundos eram semelhantes a rãs."},
 {"t":"cv","p":"Os reis foram reunidos no lugar que, em hebraico, é chamado de Armagedom.","c":true,"v":16,"e":"O versículo 16 diz que os reis foram reunidos no lugar chamado, em hebraico, de Armagedom."},
 {"t":"cv","p":"O sétimo anjo derramou a sua taça no mar.","c":false,"v":17,"e":"O versículo 17 diz que o sétimo anjo derramou a sua taça no ar, e não no mar."},
 {"t":"cv","p":"Depois da grande chuva de pedras, as pessoas se arrependeram e deram glória a Deus.","c":false,"v":21,"e":"O versículo 21 diz que as pessoas blasfemaram contra Deus por causa da chuva de pedras."}
]}

Apocalipse 20 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o anjo que desceu do céu tinha na mão?","o":["A chave do abismo e uma grande corrente","Uma espada afiada e um escudo","Um livro selado e uma trombeta","Uma coroa de ouro e um cetro"],"c":0,"v":1,"e":"O versículo 1 diz que o anjo tinha na mão a chave do abismo e uma grande corrente."},
 {"t":"multipla","p":"Por que o dragão foi lançado no abismo, fechado e selado?","o":["Para que não pudesse mais falar","Para que fosse julgado diante do trono","Para que não mais enganasse as nações até se completarem os mil anos","Para que os anjos o vigiassem para sempre"],"c":2,"v":3,"e":"O versículo 3 explica que o abismo foi selado para que ele não mais enganasse as nações até que se completassem os mil anos."},
 {"t":"multipla","p":"Quem João viu viver e reinar com Cristo durante mil anos?","o":["Os reis da terra e seus exércitos","As almas dos decapitados por causa do testemunho de Jesus e da palavra de Deus","Os anjos que guardavam o abismo","Todos os mortos do mar"],"c":1,"v":4,"e":"No versículo 4, as almas dos decapitados por causa do testemunho de Jesus e da palavra de Deus viveram e reinaram com Cristo mil anos."},
 {"t":"multipla","p":"O que aconteceu com as nações que cercaram o acampamento dos santos e a cidade amada?","o":["Foram engolidas pela terra","Fugiram para os quatro cantos da terra","Fizeram as pazes com os santos","Desceu fogo do céu e as consumiu"],"c":3,"v":9,"e":"O versículo 9 diz que desceu fogo do céu e consumiu os que cercavam o acampamento dos santos."},
 {"t":"multipla","p":"Diante do grande trono branco, segundo o que os mortos foram julgados?","o":["Segundo a sua nação","Segundo a sua idade","Segundo as suas obras","Segundo a sua riqueza"],"c":2,"v":12,"e":"O versículo 12 diz que os mortos foram julgados segundo as suas obras, conforme o que estava escrito nos livros."},
 {"t":"cv","p":"Quando os mil anos se completarem, Satanás continuará preso para sempre.","c":false,"v":7,"e":"O versículo 7 diz que, completados os mil anos, Satanás será solto de sua prisão."},
 {"t":"cv","p":"O diabo foi lançado no lago de fogo e enxofre, onde já estavam a besta e o falso profeta.","c":true,"v":10,"e":"O versículo 10 afirma que o diabo foi lançado no lago de fogo e enxofre, onde já se encontravam a besta e o falso profeta."},
 {"t":"cv","p":"Quem não foi encontrado registrado no Livro da Vida foi lançado no lago de fogo.","c":true,"v":15,"e":"O versículo 15 diz que quem não foi encontrado registrado no Livro da Vida foi lançado no lago de fogo."}
]}

Apocalipse 19 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que a multidão no céu diz que os juízos de Deus são verdadeiros e justos?","o":["Porque Ele julgou a grande meretriz","Porque Ele derrotou o dragão","Porque Ele abriu o sétimo selo","Porque Ele reconstruiu o templo"],"c":0,"v":2,"e":"No versículo 2, a multidão diz que os juízos de Deus são justos porque Ele julgou a grande meretriz que corrompia a terra."},
 {"t":"multipla","p":"Quem se prostrou e adorou a Deus dizendo \"Amém! Aleluia!\"?","o":["Os sete anjos das trombetas","Os doze apóstolos","Os vinte e quatro anciãos e os quatro seres viventes","Os mártires que estavam debaixo do altar"],"c":2,"v":4,"e":"O versículo 4 diz que os vinte e quatro anciãos e os quatro seres viventes se prostraram e adoraram a Deus dizendo \"Amém! Aleluia!\"."},
 {"t":"multipla","p":"Com que foi concedido à esposa do Cordeiro vestir-se?","o":["Com púrpura e escarlate","Com linho finíssimo, puro e resplandecente","Com vestes bordadas de ouro","Com pano de saco"],"c":1,"v":8,"e":"O versículo 8 diz que lhe foi concedido vestir-se de linho finíssimo, puro e resplandecente."},
 {"t":"multipla","p":"O que o anjo disse quando João se prostrou aos seus pés para adorá-lo?","o":["Levanta-te e escreve","Sobe aqui","Não temas","Não faças isso! Adora a Deus"],"c":3,"v":10,"e":"No versículo 10, o anjo diz a João \"Não faças isso!\", afirma ser seu conservo e manda que ele adore a Deus."},
 {"t":"multipla","p":"Como se chama o cavaleiro do cavalo branco que João vê quando o céu se abre?","o":["Fiel e Verdadeiro","Alfa e Ômega","Leão de Judá","Estrela da Manhã"],"c":0,"v":11,"e":"O versículo 11 diz que o cavaleiro do cavalo branco se chama Fiel e Verdadeiro."},
 {"t":"cv","p":"No manto e na coxa do cavaleiro está escrito o nome \"Rei dos Reis e Senhor dos Senhores\".","c":true,"v":16,"e":"O versículo 16 diz que no seu manto e na sua coxa está inscrito o nome \"Rei dos Reis e Senhor dos Senhores\"."},
 {"t":"cv","p":"O anjo que estava em pé no sol convocou os exércitos do céu para a batalha.","c":false,"v":17,"e":"No versículo 17, o anjo em pé no sol chama as aves que voam pelo meio do céu para a grande ceia de Deus, e não os exércitos."},
 {"t":"cv","p":"A besta e o falso profeta foram lançados vivos no lago de fogo que arde com enxofre.","c":true,"v":20,"e":"O versículo 20 diz que a besta e o falso profeta foram lançados vivos no lago de fogo que arde com enxofre."}
]}

Apocalipse 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por meio de quem a revelação foi enviada a João?","o":["De um profeta","Do seu anjo","Dos sete Espíritos","De um ancião"],"c":1,"v":1,"e":"O versículo 1 diz que Deus a enviou por intermédio de seu anjo ao seu servo João."},
 {"t":"multipla","p":"Segundo o capítulo, como Jesus vem?","o":["Com as nuvens","Montado num cavalo branco","Com fogo do céu","Em segredo, de noite"],"c":0,"v":7,"e":"O versículo 7 diz: \"Eis que vem com as nuvens, e todo olho o verá\"."},
 {"t":"multipla","p":"Em que ilha João estava quando teve a visão?","o":["Creta","Chipre","Patmos","Malta"],"c":2,"v":9,"e":"No versículo 9, João diz que se achou na ilha chamada Patmos."},
 {"t":"multipla","p":"Como era a grande voz que João ouviu por trás de si?","o":["Como de trovão","Como de trombeta","Como de leão","Como de harpa"],"c":1,"v":10,"e":"O versículo 10 diz que João ouviu uma grande voz, como de trombeta."},
 {"t":"multipla","p":"O que João viu quando se voltou para ver quem falava com ele?","o":["Um trono de marfim","Sete trombetas","Um altar de bronze","Sete candeeiros de ouro"],"c":3,"v":12,"e":"No versículo 12, ao se voltar, João viu sete candeeiros de ouro."},
 {"t":"cv","p":"Aquele que estava no meio dos candeeiros tinha sete estrelas na mão direita.","c":true,"v":16,"e":"O versículo 16 diz que ele tinha na mão direita sete estrelas."},
 {"t":"cv","p":"Quando João caiu aos seus pés como morto, ele lhe disse: \"Levante-se e vá embora\".","c":false,"v":17,"e":"No versículo 17, ele pôs a mão direita sobre João e disse: \"Não temas; eu sou o primeiro e o último\"."},
 {"t":"cv","p":"As sete estrelas representam as sete igrejas.","c":false,"v":20,"e":"O versículo 20 diz que as sete estrelas são os anjos das sete igrejas e que os sete candeeiros representam as sete igrejas."}
]}

Apocalipse 15 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que os sete anjos do sinal no céu tinham?","o":["Sete trombetas","Os sete últimos flagelos","Sete selos","Sete candelabros"],"c":1,"v":1,"e":"No versículo 1, os sete anjos tinham os sete últimos flagelos, com os quais se consumou a ira de Deus."},
 {"t":"multipla","p":"Onde estavam em pé os que venceram a besta?","o":["Diante do trono","Sobre o monte Sião","Junto ao altar","Junto ao mar de vidro"],"c":3,"v":2,"e":"O versículo 2 diz que eles estavam em pé junto ao mar de vidro mesclado com fogo."},
 {"t":"multipla","p":"Que cânticos os vencedores entoavam?","o":["O cântico de Moisés e o do Cordeiro","O cântico de Davi e o do Cordeiro","O cântico de Moisés e o de Miriã","O cântico dos vinte e quatro anciãos"],"c":0,"v":3,"e":"O versículo 3 diz que entoavam o cântico de Moisés, servo de Deus, e o cântico do Cordeiro."},
 {"t":"multipla","p":"O que João viu ser aberto no céu?","o":["O livro selado","O poço do abismo","O santuário da tenda do Testemunho","Uma porta no céu"],"c":2,"v":5,"e":"O versículo 5 diz que João viu o santuário da tenda do Testemunho ser aberto no céu."},
 {"t":"multipla","p":"Quem deu aos sete anjos as sete taças de ouro?","o":["Um dos vinte e quatro anciãos","Um dos quatro seres viventes","O Cordeiro","Um anjo forte"],"c":1,"v":7,"e":"O versículo 7 diz que um dos quatro seres viventes deu aos sete anjos as sete taças cheias da cólera de Deus."},
 {"t":"cv","p":"O cântico diz que todas as nações virão e adorarão diante de Deus.","c":true,"v":4,"e":"O versículo 4 diz que todas as nações virão e adorarão diante dele, porque seus atos de justiça se tornaram evidentes."},
 {"t":"cv","p":"Os sete anjos saíram do santuário vestidos de pano de saco.","c":false,"v":6,"e":"O versículo 6 diz que eles saíram vestidos de linho puro e resplandecente."},
 {"t":"cv","p":"Ninguém podia entrar no templo até que se cumprissem as sete pragas dos sete anjos.","c":true,"v":8,"e":"O versículo 8 diz que o templo se encheu de fumaça e ninguém podia entrar até que se cumprissem as sete pragas."}
]}

Apocalipse 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que João viu no céu no começo do capítulo?","o":["Uma porta aberta","Uma escada de ouro","Um anjo com uma espada","Uma nuvem de fogo"],"c":0,"v":1,"e":"No versículo 1, João olha e vê uma porta aberta no céu, e a voz como de trombeta o chama para subir."},
 {"t":"multipla","p":"O arco-íris ao redor do trono tinha a aparência de quê?","o":["Safira","Esmeralda","Rubi","Ouro"],"c":1,"v":3,"e":"No versículo 3, o arco-íris ao redor do trono tem a aparência de esmeralda."},
 {"t":"multipla","p":"O que os vinte e quatro anciãos tinham sobre a cabeça?","o":["Mitras de linho","Coroas de prata","Coroas de ouro","Coroas de espinhos"],"c":2,"v":4,"e":"No versículo 4, os anciãos estão vestidos de branco e têm coroas de ouro sobre a cabeça."},
 {"t":"multipla","p":"O que representam as sete tochas de fogo que ardiam diante do trono?","o":["As sete igrejas","Os sete anjos","Os sete selos","Os sete Espíritos de Deus"],"c":3,"v":5,"e":"No versículo 5, as sete tochas de fogo representam os sete Espíritos de Deus."},
 {"t":"multipla","p":"A que era semelhante o quarto ser vivente?","o":["Um leão","Uma águia em pleno voo","Um novilho","Um homem"],"c":1,"v":7,"e":"No versículo 7, o quarto ser vivente é semelhante a uma águia em pleno voo."},
 {"t":"cv","p":"Diante do trono havia um mar de vidro, semelhante ao cristal.","c":true,"v":6,"e":"O versículo 6 diz que havia diante do trono um mar de vidro, semelhante ao cristal."},
 {"t":"cv","p":"Os quatro seres viventes descansavam durante a noite.","c":false,"v":8,"e":"O versículo 8 diz que eles não descansavam nem de dia nem de noite, proclamando: Santo, Santo, Santo."},
 {"t":"cv","p":"Os vinte e quatro anciãos lançavam suas coroas diante do trono.","c":true,"v":10,"e":"No versículo 10, os anciãos se prostram, adoram e lançam suas coroas diante do trono."}
]}

Apocalipse 22 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde brotava o rio da água da vida?","o":["Do trono de Deus e do Cordeiro","Do templo da cidade","Do monte Sião","Da árvore da vida"],"c":0,"v":1,"e":"O versículo 1 diz que o rio brotava do trono de Deus e do Cordeiro."},
 {"t":"multipla","p":"Para que servem as folhas da árvore da vida?","o":["Para alimentar os anjos","Para a cura das nações","Para cobrir os servos de Deus","Para enfeitar a praça da cidade"],"c":1,"v":2,"e":"O versículo 2 diz que as folhas da árvore servem para a cura das nações."},
 {"t":"multipla","p":"Quando João se prostrou para adorar o anjo, o que o anjo lhe disse?","o":["Levanta-te e escreve","Recebe a minha bênção","Não faças isso; adora a Deus","Sela as palavras deste livro"],"c":2,"v":9,"e":"No versículo 9 o anjo diz a João que não faça isso, pois é servo como ele, e manda adorar a Deus."},
 {"t":"multipla","p":"Por que João não devia selar as palavras da profecia?","o":["Porque o livro ainda não estava completo","Porque só os profetas podiam lê-lo","Porque o anjo voltaria para buscá-lo","Porque o tempo está próximo"],"c":3,"v":10,"e":"No versículo 10 o anjo diz para não selar as palavras porque o tempo está próximo."},
 {"t":"multipla","p":"Como Jesus se apresenta no fim do capítulo?","o":["A raiz e a geração de Davi, a radiante estrela da manhã","O pão da vida e a luz do mundo","O leão de Judá e o pastor de Israel","O filho de Abraão e a pedra angular"],"c":0,"v":16,"e":"No versículo 16 Jesus diz que é a raiz e a geração de Davi, a radiante estrela da manhã."},
 {"t":"cv","p":"Na cidade ainda será preciso a luz do sol, porque lá continuará havendo noite.","c":false,"v":5,"e":"O versículo 5 diz que ali não haverá mais noite nem precisarão da luz do sol, pois o Senhor Deus brilhará sobre eles."},
 {"t":"cv","p":"Quem tem sede é convidado a receber de graça a água da vida.","c":true,"v":17,"e":"O versículo 17 diz que quem tem sede venha e quem quiser receba de graça a água da vida."},
 {"t":"cv","p":"Quem retirar algo das palavras do livro desta profecia terá sua parte tirada da árvore da vida e da Cidade Santa.","c":true,"v":19,"e":"O versículo 19 diz que Deus tirará a parte dessa pessoa da árvore da vida e da Cidade Santa."}
]}

Apocalipse 18 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que aconteceu com a terra quando o anjo de grande autoridade desceu do céu?","o":["Ela se iluminou com a glória dele","Ela tremeu","Ela ficou em trevas","Ela se abriu"],"c":0,"v":1,"e":"O versículo 1 diz que a terra se iluminou com a glória do anjo."},
 {"t":"multipla","p":"O que a outra voz do céu manda o povo de Deus fazer?","o":["Chorar por Babilônia","Retirar-se de Babilônia","Reconstruir Babilônia","Avisar os reis da terra"],"c":1,"v":4,"e":"No versículo 4 a voz diz: \"Retirai-vos dela, povo meu\", para não participarem de seus pecados e pragas."},
 {"t":"multipla","p":"O que Babilônia diz em seu coração?","o":["Sou a maior de todas as cidades","Ninguém poderá me julgar","Estou assentada como rainha, não sou viúva","Meus mercadores me protegerão"],"c":2,"v":7,"e":"O versículo 7 traz a fala dela: \"Estou assentada como rainha, não sou viúva e nunca verei o pranto\"."},
 {"t":"multipla","p":"Por que os mercadores da terra choram por Babilônia?","o":["Porque perderam seus navios","Porque foram presos pelos reis","Porque a cidade os expulsou","Porque ninguém mais compra suas mercadorias"],"c":3,"v":11,"e":"O versículo 11 diz que eles choram porque já ninguém compra suas mercadorias."},
 {"t":"multipla","p":"O que os marinheiros clamaram ao ver a fumaça do incêndio?","o":["Fujamos para longe desta cidade!","Que cidade se compara a esta grande cidade?","Deus é justo em seus juízos!","Quem nos pagará agora?"],"c":1,"v":18,"e":"No versículo 18 eles clamam: \"Que cidade se compara a esta grande cidade?\"."},
 {"t":"cv","p":"Os céus, os santos, os apóstolos e os profetas são chamados a chorar por Babilônia.","c":false,"v":20,"e":"O versículo 20 os chama a se alegrar, porque Deus julgou a causa deles contra ela."},
 {"t":"cv","p":"Um anjo forte levantou uma pedra como uma grande mó e a lançou no mar.","c":true,"v":21,"e":"O versículo 21 diz que o anjo arrojou a pedra no mar, mostrando como Babilônia seria arremessada."},
 {"t":"cv","p":"Na cidade se encontrou o sangue dos profetas e dos santos.","c":true,"v":24,"e":"O versículo 24 diz que nela se encontrou o sangue dos profetas, dos santos e de todos os mortos sobre a terra."}
]}

Apocalipse 14 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde João viu o Cordeiro em pé com os cento e quarenta e quatro mil?","o":["No monte das Oliveiras","No monte Sião","No monte Sinai","No monte Carmelo"],"c":1,"v":1,"e":"O versículo 1 diz que o Cordeiro estava em pé no monte Sião com os cento e quarenta e quatro mil."},
 {"t":"multipla","p":"Quem podia aprender o cântico novo cantado diante do trono?","o":["Os quatro seres viventes","Os anciãos","Os cento e quarenta e quatro mil","Os santos anjos"],"c":2,"v":3,"e":"O versículo 3 diz que ninguém podia aprender o cântico, exceto os cento e quarenta e quatro mil comprados da terra."},
 {"t":"multipla","p":"O que o anjo com o evangelho eterno diz em alta voz?","o":["Arrependam-se, pois o reino está próximo","Temam a Deus e deem-lhe glória","Saiam dela, povo meu","Preparem o caminho do Senhor"],"c":1,"v":7,"e":"No versículo 7 o anjo diz: Temam a Deus e deem-lhe glória, pois é chegada a hora do Seu juízo."},
 {"t":"multipla","p":"O que o segundo anjo anuncia?","o":["Que a besta foi lançada no fogo","Que a hora da colheita chegou","Que caiu a grande Babilônia","Que o templo de Deus foi aberto"],"c":2,"v":8,"e":"O versículo 8 traz o anúncio do segundo anjo: Caiu, caiu a grande Babilônia."},
 {"t":"multipla","p":"Segundo o terceiro anjo, quem adorar a besta e receber sua marca beberá de quê?","o":["Do vinho da cólera de Deus","Da água da vida","Do cálice da salvação","Do vinho da prostituição de Babilônia"],"c":0,"v":10,"e":"O versículo 10 diz que essa pessoa beberá do vinho da cólera de Deus, preparado sem mistura no cálice da sua ira."},
 {"t":"cv","p":"A voz do céu manda escrever que são bem-aventurados os mortos que, desde agora, morrem no Senhor.","c":true,"v":13,"e":"O versículo 13 traz essas palavras e acrescenta que eles descansam das suas fadigas."},
 {"t":"cv","p":"Aquele que estava sentado sobre a nuvem passou a sua foice sobre a terra, e a terra foi ceifada.","c":true,"v":16,"e":"O versículo 16 diz exatamente que ele passou a foice sobre a terra e a terra foi ceifada."},
 {"t":"cv","p":"O lagar da cólera de Deus foi pisado dentro da cidade.","c":false,"v":20,"e":"O versículo 20 diz que o lagar foi pisado fora da cidade."}
]}

Apocalipse 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde estava o livro selado que João viu?","o":["Na mão direita daquele que estava assentado no trono","Sobre o altar diante do trono","Nas mãos do anjo forte","No meio dos vinte e quatro anciãos"],"c":0,"v":1,"e":"O versículo 1 diz que o livro estava na mão direita daquele que estava assentado no trono."},
 {"t":"multipla","p":"Por que João chorava muito?","o":["Porque o anjo forte o repreendeu","Porque ninguém foi encontrado digno de abrir o livro","Porque viu o Cordeiro como se tivesse sido morto","Porque não conseguia ler o que estava escrito no livro"],"c":1,"v":4,"e":"O versículo 4 diz que João chorava porque ninguém foi encontrado digno de abrir o livro, nem de vê-lo."},
 {"t":"multipla","p":"Quem disse a João: \"Não chores\"?","o":["O anjo forte","Um dos quatro seres viventes","Um dos anciãos","O próprio Cordeiro"],"c":2,"v":5,"e":"O versículo 5 diz que foi um dos anciãos quem falou com João."},
 {"t":"multipla","p":"Depois que o ancião falou do Leão da tribo de Judá, o que João viu no meio do trono?","o":["Um leão rugindo","Um anjo com uma espada","Um cavaleiro vestido de branco","Um Cordeiro de pé, como se tivesse sido morto"],"c":3,"v":6,"e":"O versículo 6 diz que João olhou e viu um Cordeiro de pé, como se tivesse sido morto."},
 {"t":"multipla","p":"O que eram as taças de ouro cheias de incenso?","o":["As orações dos santos","Os sete Espíritos de Deus","O sangue do Cordeiro","Os louvores dos anjos"],"c":0,"v":8,"e":"O versículo 8 explica que as taças de incenso são as orações dos santos."},
 {"t":"cv","p":"No novo cântico, os seres viventes e os anciãos dizem que o Cordeiro comprou para Deus, com o seu sangue, gente de toda tribo, língua, povo e nação.","c":true,"v":9,"e":"O versículo 9 diz isso no novo cântico."},
 {"t":"cv","p":"Somente os anjos do céu louvaram aquele que está assentado no trono e o Cordeiro.","c":false,"v":13,"e":"O versículo 13 diz que toda criatura no céu, sobre a terra, debaixo da terra e no mar deu o louvor."},
 {"t":"cv","p":"No fim do capítulo, os quatro seres viventes respondiam \"Amém!\" e os vinte e quatro anciãos se prostraram e adoraram.","c":true,"v":14,"e":"O versículo 14 descreve o amém dos seres viventes e a adoração dos anciãos."}
]}

Apocalipse 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde João viu emergir a primeira besta?","o":["Do mar","Da terra","Do céu","Do abismo"],"c":0,"v":1,"e":"No versículo 1, João está sobre a areia do mar e vê a besta emergir do mar."},
 {"t":"multipla","p":"Quem deu à besta seu poder, seu trono e grande autoridade?","o":["A segunda besta","O dragão","Os reis da terra","Os habitantes da terra"],"c":1,"v":2,"e":"O versículo 2 diz que o dragão lhe concedeu seu poder, seu trono e uma grande autoridade."},
 {"t":"multipla","p":"O que aconteceu com uma das cabeças da besta?","o":["Foi cortada e jogada no mar","Recebeu um diadema a mais","Foi ferida de morte, mas a ferida foi curada","Foi queimada com fogo do céu"],"c":2,"v":3,"e":"O versículo 3 diz que uma das cabeças estava como ferida de morte, mas a ferida mortal foi curada."},
 {"t":"multipla","p":"Quem vai adorar a besta, segundo o capítulo?","o":["Somente os reis e os poderosos","Os que habitam no céu","Os santos que foram vencidos","Os que não têm o nome escrito no Livro da Vida do Cordeiro"],"c":3,"v":8,"e":"O versículo 8 diz que a adorarão os habitantes da terra cujos nomes não estão escritos no Livro da Vida do Cordeiro."},
 {"t":"multipla","p":"Como era a segunda besta, que emergiu da terra?","o":["Tinha dois chifres como de cordeiro, mas falava como dragão","Tinha sete cabeças e dez chifres","Era semelhante a um leopardo","Tinha boca de leão e pés de urso"],"c":0,"v":11,"e":"O versículo 11 descreve a outra besta com dois chifres semelhantes aos de um cordeiro, mas falando como um dragão."},
 {"t":"cv","p":"A segunda besta fazia até fogo descer do céu à terra, diante dos homens.","c":true,"v":13,"e":"O versículo 13 diz que ela opera grandes sinais, a ponto de fazer descer fogo do céu à terra."},
 {"t":"cv","p":"Somente os ricos e os livres eram obrigados a receber a marca.","c":false,"v":16,"e":"O versículo 16 diz que todos recebem a marca: pequenos e grandes, ricos e pobres, livres e escravos."},
 {"t":"cv","p":"O capítulo diz que o número da besta é número de homem e que esse número é seiscentos e sessenta e seis.","c":true,"v":18,"e":"O versículo 18 afirma que é número de homem e que o seu número é seiscentos e sessenta e seis."}
]}

Apocalipse 6 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que tinha o cavaleiro do cavalo branco?","o":["Uma espada","Um arco","Uma balança","Um cetro"],"c":1,"v":2,"e":"O versículo 2 diz que o cavaleiro do cavalo branco tinha um arco e recebeu uma coroa."},
 {"t":"multipla","p":"O que foi dado ao cavaleiro do cavalo vermelho?","o":["Uma coroa para reinar sobre a terra","Uma balança para medir o trigo","Autoridade para trazer a fome","Tirar a paz da terra e uma grande espada"],"c":3,"v":4,"e":"O versículo 4 diz que lhe foi dado tirar a paz da terra e foi-lhe entregue uma grande espada."},
 {"t":"multipla","p":"Depois que apareceu o cavalo preto, o que a voz no meio dos seres viventes mandou não danificar?","o":["O azeite e o vinho","O trigo e a cevada","As árvores e o mar","O templo e o altar"],"c":0,"v":6,"e":"No versículo 6, a voz fala do preço do trigo e da cevada e diz: não danifiques o azeite e o vinho."},
 {"t":"multipla","p":"Como se chamava o que montava o cavalo amarelo?","o":["Fome","Guerra","Morte","Destruidor"],"c":2,"v":8,"e":"O versículo 8 diz que o cavaleiro do cavalo amarelo se chamava Morte e que o Inferno o seguia."},
 {"t":"multipla","p":"Ao abrir o quinto selo, o que João viu debaixo do altar?","o":["Os quatro seres viventes adorando","As almas dos que foram mortos por causa da palavra de Deus","Um anjo com um incensário de ouro","Os vinte e quatro anciãos com coroas"],"c":1,"v":9,"e":"O versículo 9 diz que debaixo do altar estavam as almas dos mortos por causa da palavra de Deus e do testemunho que sustentavam."},
