 {"t":"cv","p":"Ao abrir o sexto selo, o sol ficou vermelho como sangue.","c":false,"v":12,"e":"O versículo 12 diz que o sol se tornou negro como saco de cilício e que a lua é que ficou como sangue."},
 {"t":"cv","p":"Os que se esconderam nas cavernas pediam aos montes e às rochas que caíssem sobre eles.","c":true,"v":16,"e":"O versículo 16 diz que eles diziam aos montes e às rochas: caí sobre nós e escondei-nos da ira do Cordeiro."}
]}

Apocalipse 10 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que havia por cima da cabeça do anjo forte que desceu do céu?","o":["Uma coroa de ouro","Um arco-íris","Uma estrela brilhante","Uma chama de fogo"],"c":1,"v":1,"e":"O versículo 1 diz que por cima da cabeça do anjo havia um arco-íris."},
 {"t":"multipla","p":"Onde o anjo colocou os pés?","o":["Os dois pés sobre o mar","Os dois pés sobre uma nuvem","O pé direito sobre o mar e o esquerdo sobre a terra","O pé direito sobre a terra e o esquerdo sobre o mar"],"c":2,"v":2,"e":"O versículo 2 diz que ele colocou o pé direito sobre o mar e o esquerdo sobre a terra."},
 {"t":"multipla","p":"Como era o brado do anjo?","o":["Como o som de muitas águas","Como o toque de uma trombeta","Como um vento forte","Como o rugido de um leão"],"c":3,"v":3,"e":"O versículo 3 diz que ele bradou em alta voz, como o rugido de um leão."},
 {"t":"multipla","p":"O que a voz do céu mandou João fazer com o que os sete trovões falaram?","o":["Guardar em segredo e não escrever","Escrever tudo num livro","Anunciar às sete igrejas","Repetir em alta voz"],"c":0,"v":4,"e":"No versículo 4 a voz do céu diz: \"Guarda em segredo as coisas que os sete trovões falaram e não as escrevas\"."},
 {"t":"multipla","p":"O que o anjo jurou, com a mão direita levantada para o céu?","o":["Que o livrinho seria selado","Que não haveria mais demora","Que os trovões falariam de novo","Que o mar seria secado"],"c":1,"v":6,"e":"O versículo 6 diz que o anjo jurou por Aquele que vive pelos séculos dos séculos que não haveria mais demora."},
